import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Erasure Coding- 5 Ways to Split a Squid - Jamie Pryde, IBM","description":"","frontmatter":{"title":"Erasure Coding- 5 Ways to Split a Squid - Jamie Pryde, IBM","date":"2025-01-26T00:00:00.000Z","updated":"2025-01-26T00:00:00.000Z","tags":["Ceph","Erasure Coding","性能优化","存储系统","数据冗余"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Erasure_Coding_-_5_Ways_to_Split_a_Squid_-_Jamie_Pryde_IBM.md","filePath":"posts/2025/Erasure_Coding_-_5_Ways_to_Split_a_Squid_-_Jamie_Pryde_IBM.md","lastUpdated":1780459816000}'),t={name:"posts/2025/Erasure_Coding_-_5_Ways_to_Split_a_Squid_-_Jamie_Pryde_IBM.md"};function s(n,r,l,d,u,_){return a(),i("div",null,[...r[0]||(r[0]=[o('<h3 id="会议纪要-ceph中erasure-coding插件的性能优化讨论" tabindex="-1">会议纪要：Ceph中Erasure Coding插件的性能优化讨论 <a class="header-anchor" href="#会议纪要-ceph中erasure-coding插件的性能优化讨论" aria-label="Permalink to &quot;会议纪要：Ceph中Erasure Coding插件的性能优化讨论&quot;">​</a></h3><p><strong>会议主题</strong>：Ceph中Erasure Coding插件的性能优化及使用建议</p><p><strong>主讲人</strong>：Jamie Pride（IBM英国，软件开发工程师，专注于Ceph的Erasure Coding性能优化）</p><p><strong>会议时间</strong>：未知</p><h4 id="_1-会议背景" tabindex="-1">1. <strong>会议背景</strong> <a class="header-anchor" href="#_1-会议背景" aria-label="Permalink to &quot;1. **会议背景**&quot;">​</a></h4><ul><li>Jamie Pride在IBM工作近10年，主要从事存储系统开发，过去一年专注于Ceph的Erasure Coding性能优化，特别是针对块存储和文件存储工作负载的性能提升。</li><li>本次会议主要讨论Ceph中Erasure Coding的不同插件及其性能表现，并分享一些优化建议。</li></ul><h4 id="_2-主要议题" tabindex="-1">2. <strong>主要议题</strong> <a class="header-anchor" href="#_2-主要议题" aria-label="Permalink to &quot;2. **主要议题**&quot;">​</a></h4><ul><li><p><strong>Erasure Coding简介</strong>：</p><ul><li>Erasure Coding是一种数据保护机制，通过将数据分成多个数据块（K）和生成额外的校验块（M）来实现数据冗余。</li><li>相比于传统的三副本复制（3X replication），Erasure Coding可以显著降低存储开销，例如4+2的Erasure Coding配置（K=4, M=2）仅需要1.5倍的存储开销。</li><li>Erasure Coding的灵活性允许设置不同的M值，例如M=3或M=4，以提高容错能力，但会增加存储开销和性能成本。</li></ul></li><li><p><strong>支持的Erasure Coding插件</strong>：</p><ul><li><strong>Jerasure</strong>：Ceph的默认Erasure Coding插件，广泛使用，但不支持现代的AVX指令集，且不再维护。</li><li><strong>ISA-L（Intel Storage Acceleration Library）</strong>：支持Intel、AMD和ARM CPU，且支持AVX、AVX2和AVX512指令集，性能优于Jerasure，且仍在维护。</li><li><strong>LRC、Shec、Clay</strong>：这些插件旨在优化OSD故障时的恢复效率，但使用较少。</li></ul></li><li><p><strong>性能基准测试</strong>：</p><ul><li>使用Ceph的Erasure Code Benchmark工具对不同插件进行性能测试，结果显示ISA-L在现代CPU上（支持AVX512）的编码和解码性能比Jerasure高出4到5倍。</li><li>即使在仅支持AVX2的AMD CPU上，ISA-L的性能也比Jerasure高出约2倍。</li></ul></li><li><p><strong>Telemetry数据分析</strong>：</p><ul><li>从Ceph的Telemetry数据来看，约有1/4到1/3的Ceph集群使用Erasure Coding，其中大部分使用Jerasure插件和默认的Reed Solomon Vandermonde算法。</li><li>大多数用户使用默认配置，较少尝试其他插件如LRC、Shec等。</li></ul></li></ul><h4 id="_3-决定事项" tabindex="-1">3. <strong>决定事项</strong> <a class="header-anchor" href="#_3-决定事项" aria-label="Permalink to &quot;3. **决定事项**&quot;">​</a></h4><ul><li><strong>推荐使用ISA-L插件</strong>：由于ISA-L在现代CPU上的性能优势明显，建议在新建Erasure Coding池时使用ISA-L插件。</li><li><strong>考虑LRC、Shec、Clay插件</strong>：这些插件在特定场景下（如网络带宽受限时）可以加速OSD故障后的恢复，但因其使用较少，建议谨慎使用。</li></ul><h4 id="_4-后续行动计划" tabindex="-1">4. <strong>后续行动计划</strong> <a class="header-anchor" href="#_4-后续行动计划" aria-label="Permalink to &quot;4. **后续行动计划**&quot;">​</a></h4><ul><li><strong>更改默认插件</strong>：Jamie Pride已提交一个Pull Request，建议将ISA-L设为新建Erasure Coding池的默认插件。</li><li><strong>进一步优化</strong>：Connor Fet将在后续的会议中分享更多关于Erasure Coding性能优化的更新，特别是针对块存储工作负载的部分写入和读取优化。</li></ul><h4 id="_5-q-a及讨论" tabindex="-1">5. <strong>Q&amp;A及讨论</strong> <a class="header-anchor" href="#_5-q-a及讨论" aria-label="Permalink to &quot;5. **Q&amp;A及讨论**&quot;">​</a></h4><ul><li>会议结束后，团队成员（包括团队负责人Mebu Scales和Connor Fet）将继续提供支持，欢迎与会者进一步讨论Erasure Coding插件及性能优化相关问题。</li></ul><p><strong>总结</strong>：本次会议详细讨论了Ceph中Erasure Coding的不同插件及其性能表现，特别是Jerasure和ISA-L的对比。ISA-L由于支持现代CPU指令集且仍在维护，性能显著优于Jerasure。会议建议在新建Erasure Coding池时优先考虑使用ISA-L插件，并计划将其设为默认插件。</p>',15)])])}const C=e(t,[["render",s]]);export{p as __pageData,C as default};
